import os, urllib.request, json
key=os.environ.get('RENDER_API_KEY','')
service=os.environ.get('RENDER_SERVICE_ID','')
print('key_present',bool(key),'service_present',bool(service))
headers={'Authorization':f'Bearer {key}','Accept':'application/json'}
for label,url in [('owners','https://api.render.com/v1/owners'),('service',f'https://api.render.com/v1/services/{service}'),('deploys',f'https://api.render.com/v1/services/{service}/deploys?limit=5')]:
 request=urllib.request.Request(url,headers=headers)
 try:
  with urllib.request.urlopen(request,timeout=25) as response:
   payload=json.load(response)
   print(label,'HTTP',response.status)
   if label=='owners': print('owner_count',len(payload) if isinstance(payload,list) else 'object')
   elif label=='service': print('service_id',payload.get('id'),'service_name',payload.get('name'),'service_type',payload.get('type'),'suspended',payload.get('suspended'))
   else:
    values=payload if isinstance(payload,list) else payload.get('data',[])
    print('deploy_count',len(values))
    for item in values[:5]: print('deploy',item.get('id'),item.get('status'),item.get('commit',{}).get('id') if isinstance(item.get('commit'),dict) else item.get('commitId'),item.get('createdAt'),item.get('finishedAt'))
 except urllib.error.HTTPError as err:
  print(label,'HTTP',err.code)
 except Exception as err:
  print(label,'ERROR',type(err).__name__,str(err)[:200])
PY

